python3 - <<'PY'
p='src/types/checker/inference/objects/methods.rs'
s=open(p).read()
old = """                        let by_ref = sig.ref_params.get(i).copied().unwrap_or(false);
                        let current = sig.params[i].1.clone();
                        if !(by_ref && by_ref_param_is_widened(&current)) {
                            sig.params[i].1 =
                                Self::specialize_generic_array_param_hint(&current, arg_ty);
                        }"""
n = s.count(old)
assert n == 3, n
# each site has its own owner key; patch them one at a time with the right owner expression
owners = [
    'format!("{}::{}", impl_class_name, method_key)',
    'format!("{}::{}", class_name, php_symbol_key(method))',
    'format!("{}::{}", direct_impl_class_name, php_symbol_key(method))',
]
for owner in owners:
    new = """                        let by_ref = sig.ref_params.get(i).copied().unwrap_or(false);
                        let current = sig.params[i].1.clone();
                        let widened = by_ref
                            && self
                                .by_ref_widened_params
                                .contains(&(%s, i));
                        if !widened {
                            sig.params[i].1 =
                                Self::specialize_generic_array_param_hint(&current, arg_ty);
                        }""" % owner
    s = s.replace(old, new, 1)
# the standalone helper is no longer used
start = s.index("/// Returns whether a by-reference array parameter already carries boxed element slots.")
s = s[:start].rstrip() + "\n"
open(p,'w').write(s)
print('method sites consult the marker')
